    size_t live_alignment;
    bool occupied;
} tv_region;

typedef struct {
    tv_region *origin;
    uint64_t instance;
    size_t length;
    size_t alignment;
} tv_block;

enum { TV_GRANTED = 0, TV_INVALID_REQUEST = 1, TV_EXHAUSTED = 2 };
typedef struct {
    uint32_t tag;
